+  return (await o!.queryFn!()) as Riga[];
+}
+
+/** Il numero che il campanello del sito chiede, letto davvero. */
+async function numeroDelCampanello() {
+  const mod = await monta('components/hooks/useNotificationsCount.ts');
+  const usa = mod.useNotificationsCount as () => number;
+  const Campanello = () => { usa(); return null; };
+  const s = accendi(Campanello as never);
+  await attendi();
+  const o = opzioni('count');
+  s.smonta();
+  expect(o?.queryFn, 'il campanello non chiede più il conteggio').toBeTypeOf('function');
+  return (await o!.queryFn!()) as number;
+}
+
+/** Il numero che il campanello del pannello negozio chiede, letto davvero. */
+async function numeroDelPannelloNegozio() {
+  globali.__PERCORSO_FINTO__ = '/seller/dashboard';
+  globali.__PROFILO__ = {
+    isAuthenticated: true, isSeller: true,
+    profile: { id: 'u1', role: 'seller', store_name: 'Forno Bianchi', is_approved: true, approval_status: 'approved' },
