+/**
+ * @vitest-environment jsdom
+ */
+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+import { monta } from './aiuti/monta-componente';
+import { accendi, attendi } from './aiuti/schermo';
+
+/**
+ * R33-024 — Il visitatore senza account non chiede la vista dei nomi che lo rifiuta.
+ *
+ * `nomi_pubblici` si legge solo con l'account (migrazione 164). Ogni scheda prodotto (le domande
+ * sotto il prodotto) e ogni vetrina (le recensioni) la chiedevano anche per chi non ha fatto
+ * l'accesso: una richiesta rifiutata a ogni pagina e un avviso nei registri che non diceva niente.
+ * Qui le letture vere girano contro un database finto che risponde come la produzione: la vista
+ * rifiuta chi non ha l'account, `profiles` gli restituisce zero righe senza errore.
+ */
+
+const avvisi = vi.hoisted(() => ({ warn: [] as unknown[][] }));
+vi.mock('@/lib/logger', () => ({
+  logger: { warn: (...a: unknown[]) => { avvisi.warn.push(a); }, error: () => {}, info: () => {} },
+}));
+
+const globali = globalThis as Record<string, unknown>;
+const MARIA = 'a0000000-0000-4000-8000-000000000001';
+const BEPPE = 'a0000000-0000-4000-8000-000000000002';
+const PRODOTTO = 'p0000000-0000-4000-8000-000000000001';
+const NEGOZIO = 's0000000-0000-4000-8000-000000000001';
+
+/** Il database della produzione dopo la 161 e la 164, visto da `chi` (null = senza account). */
+function databaseFinto(chi: string | null) {
+  const chieste: string[] = [];
+  const client = {
+    chieste,
+    from(tabella: string) {
+      chieste.push(tabella);
+      const c: Record<string, unknown> = {};
+      const passa = () => c;
+      Object.assign(c, { select: passa, eq: passa, in: passa, order: passa, limit: passa, neq: passa });
+      const risposta = () => {
+        if (tabella === 'nomi_pubblici') {
+          return chi
+            ? { data: [{ id: BEPPE, nome: 'Beppe Neri' }], error: null }
+            : { data: null, error: { code: '42501', message: 'permission denied for view nomi_pubblici' } };
+        }
+        // Dopo la 161 `profiles` si legge solo per la propria riga: per gli altri, zero righe.
+        if (tabella === 'profiles') return { data: [], error: null };
+        if (tabella === 'product_questions') {
+          return { data: [{ id: 'q1', product_id: PRODOTTO, author_id: BEPPE, question: 'E senza glutine?', answer: null, answered_at: null, created_at: '2026-11-10T10:00:00Z' }], error: null };
+        }
+        if (tabella === 'store_reviews') {
+          return { data: [{ id: 'r1', rating: 5, comment: 'Ottimo pane', created_at: '2026-11-10T10:00:00Z', seller_reply: null, user_id: BEPPE, order_id: null, photo_urls: null, helpful_count: 0 }], error: null };
+        }
+        return { data: [], error: null };
+      };
+      c.then = (ok: (x: unknown) => unknown, ko?: (e: unknown) => unknown) => Promise.resolve(risposta()).then(ok, ko);
+      return c;
+    },
+    rpc: async () => ({ data: [], error: null }),
+  };
+  return client;
+}
+
+type Opzioni = { queryKey: readonly unknown[]; queryFn?: (c?: unknown) => Promise<unknown> };
+
+/** Monta il file vero, raccoglie la domanda che chiede e la esegue contro il database finto. */
+async function eseguiLaLettura(file: string, scegli: (o: Opzioni) => boolean, props: Record<string, unknown>, esporta = 'default') {
+  const mod = await monta(file);
+  globali.__OPZIONI_QUERY__ = [];
+  const Componente = mod[esporta] as (p: Record<string, unknown>) => unknown;
+  if (esporta === 'default') {
+    const s = accendi(Componente as never, props);
+    await attendi();
+    s.smonta();
+  } else {
+    // Il hook si chiama come una funzione: il finto di react-query non usa lo stato di React.
+    Componente(props.id as never);
+  }
+  const o = (globali.__OPZIONI_QUERY__ as Opzioni[]).filter(scegli).at(-1);
+  expect(o?.queryFn, `${file}: la lettura non c'è più`).toBeTypeOf('function');
+  return o!.queryFn!({ queryKey: o!.queryKey });
+}
+
+const domandeDelProdotto = (o: Opzioni) => JSON.stringify(o.queryKey).includes(PRODOTTO);
+const recensioniDelNegozio = (o: Opzioni) => JSON.stringify(o.queryKey) === JSON.stringify(['reviews', 'store', NEGOZIO]);
+
+beforeEach(() => {
+  avvisi.warn.length = 0;
+  globali.__PROFILO__ = { isAuthenticated: false };
+});
+afterEach(() => {
+  for (const k of ['__CLIENT_SUPABASE__', '__UTENTE__', '__OPZIONI_QUERY__', '__PROFILO__', '__DATI_QUERY__']) globali[k] = undefined;
+});
+
+describe('R33-024 — senza account la vista dei nomi non si chiede', () => {
+  it('scheda prodotto: le domande si leggono senza chiedere la vista e senza avvisi nei registri', async () => {
+    const db = databaseFinto(null);
+    globali.__CLIENT_SUPABASE__ = db;
+    globali.__UTENTE__ = null;
+    const domande = (await eseguiLaLettura('components/ProductQA.tsx', domandeDelProdotto, { productId: PRODOTTO, sellerId: NEGOZIO })) as Array<{ author: { full_name: string | null } }>;
+    expect(domande).toHaveLength(1);
+    expect(domande[0].author.full_name).toBeNull();
+    expect(db.chieste, 'il visitatore senza account chiede la vista che lo rifiuta').not.toContain('nomi_pubblici');
+    expect(avvisi.warn, 'un avviso nei registri per ogni visitatore senza account').toEqual([]);
+  }, 60000);
+
+  it('vetrina: le recensioni si leggono senza chiedere la vista e senza avvisi nei registri', async () => {
+    const db = databaseFinto(null);
+    globali.__CLIENT_SUPABASE__ = db;
+    globali.__UTENTE__ = null;
+    const recensioni = (await eseguiLaLettura('components/store-sections/useStorePageData.ts', recensioniDelNegozio, { id: NEGOZIO }, 'useStorePageData')) as Array<{ author: string | null }>;
+    expect(recensioni.map((r) => r.author)).toEqual([null]);
+    expect(db.chieste, 'il visitatore senza account chiede la vista che lo rifiuta').not.toContain('nomi_pubblici');
+    expect(avvisi.warn, 'un avviso nei registri per ogni visitatore senza account').toEqual([]);
+  }, 60000);
+
+  it('con l account la vista si chiede ancora e il nome arriva (il verde di controllo)', async () => {
+    const db = databaseFinto(MARIA);
+    globali.__CLIENT_SUPABASE__ = db;
+    globali.__UTENTE__ = { id: MARIA };
+    const domande = (await eseguiLaLettura('components/ProductQA.tsx', domandeDelProdotto, { productId: PRODOTTO, sellerId: NEGOZIO })) as Array<{ author: { full_name: string | null } }>;
+    expect(domande[0].author.full_name).toBe('Beppe');
+    expect(db.chieste).toContain('nomi_pubblici');
+    const recensioni = (await eseguiLaLettura('components/store-sections/useStorePageData.ts', recensioniDelNegozio, { id: NEGOZIO }, 'useStorePageData')) as Array<{ author: string | null }>;
+    expect(recensioni.map((r) => r.author)).toEqual(['Beppe']);
+  }, 60000);
+
+  it('fetchNomiPubblici: senza account legge solo profiles, con l account prima la vista', async () => {
+    const { fetchNomiPubblici } = await import('@/lib/queries/seller-public-profiles');
+    const senza = databaseFinto(null);
+    expect([...(await fetchNomiPubblici(senza, [BEPPE], { conAccount: false })).entries()]).toEqual([]);
+    expect(senza.chieste).toEqual(['profiles']);
+    expect(avvisi.warn).toEqual([]);
+
+    const con = databaseFinto(MARIA);
+    expect([...(await fetchNomiPubblici(con, [BEPPE], { conAccount: true })).entries()]).toEqual([[BEPPE, 'Beppe']]);
+    expect(con.chieste).toEqual(['nomi_pubblici']);
+  });
+});
